import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

/* ================= PROGRAM DATA ================= */
const programs = [
  {
    title: "Weight Training",
    img: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438",
    short:
      "Structured strength training focused on form, progression, and consistency.",
    branches: {
      "Nava India":
        "Heavy compound lifts, free weights, and structured hypertrophy training under expert supervision.",
      "RS Puram":
        "Beginner to intermediate strength training with guided machine-based workouts.",
      Kovaipudur:
        "Strength-focused routines with emphasis on functional strength and injury prevention.",
    },
  },
  {
    title: "Cardio Fitness",
    img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
    short:
      "Planned cardio workouts designed to build endurance and stamina.",
    branches: {
      "Nava India":
        "High-intensity cardio circuits using treadmills, assault bikes, and rowers.",
      "RS Puram":
        "Steady-state cardio programs focused on fat loss and endurance.",
      Kovaipudur:
        "Low-impact cardio sessions ideal for beginners and recovery phases.",
    },
  },
  {
    title: "Personal Training",
    img: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b",
    short:
      "One-on-one coaching tailored to individual fitness goals.",
    branches: {
      "Nava India":
        "Elite personal coaching with customised nutrition and workout plans.",
      "RS Puram":
        "Goal-based personal training focusing on weight loss and strength.",
      Kovaipudur:
        "Beginner-friendly personal coaching with movement correction.",
    },
  },
  {
    title: "Zumba",
    img: "https://images.unsplash.com/photo-1549576490-b0b4831ef60a",
    short:
      "Dance-based cardio sessions focused on rhythm and endurance.",
    branches: {
      "Nava India":
        "High-energy group Zumba sessions with weekly themed routines.",
    },
  },
  {
    title: "Group Training",
    img: "https://images.unsplash.com/photo-1518611012118-696072aa579a",
    short:
      "Coach-led group workouts designed for motivation and consistency.",
    branches: {
      "Nava India":
        "Strength + conditioning circuits designed for all fitness levels.",
    },
  },
  {
    title: "Functional Training",
    img: "https://images.unsplash.com/photo-1550345332-09e3ac987658",
    short:
      "Movement-based training to improve strength, balance, and mobility.",
    branches: {
      "Nava India":
        "Mobility-driven strength workouts using kettlebells and resistance bands.",
      "RS Puram":
        "Functional routines focused on daily movement efficiency.",
    },
  },
  /* EXTRA PROGRAMS (to trigger View More) */
  {
    title: "HIIT Training",
    img: "https://images.unsplash.com/photo-1599058918144-1ffabb6ab9a0",
    short: "High-intensity interval training for fat loss and endurance.",
    branches: {
      "Nava India": "Explosive HIIT sessions with strength-cardio fusion.",
    },
  },
];

/* ================= COMPONENT ================= */
export default function Programs() {
  const [active, setActive] = useState(null);
  const [showAll, setShowAll] = useState(false);
  const [branch, setBranch] = useState("");

  const visiblePrograms = showAll ? programs : programs.slice(0, 6);

  return (
    <section
      id="programs"
      className="bg-black text-white py-32 px-6 scroll-mt-28"
    >
      <div className="max-w-7xl mx-auto">
        {/* HEADING */}
        <div className="text-center max-w-3xl mx-auto mb-20">
          <h2 className="text-4xl md:text-5xl font-bold">
            Our <span className="text-[#e9b21a]">Programs</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Structured programs designed to support every fitness goal.
          </p>
        </div>

        {/* PROGRAM GRID */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {visiblePrograms.map((p, i) => (
            <motion.div
              key={i}
              whileHover={{ y: -8 }}
              transition={{ duration: 0.3 }}
              className="rounded-2xl overflow-hidden border border-white/10 bg-black shadow-xl"
            >
              <img
                src={`${p.img}?auto=format&fit=crop&w=900&q=80`}
                alt={p.title}
                className="h-56 w-full object-cover"
              />

              <div className="p-6 flex flex-col h-[220px]">
                <h3 className="text-xl font-semibold">{p.title}</h3>
                <p className="mt-3 text-sm text-gray-400 flex-1">
                  {p.short}
                </p>

                <button
                  onClick={() => {
                    setActive(p);
                    setBranch(Object.keys(p.branches)[0]);
                  }}
                  className="mt-5 w-fit px-6 py-2 rounded-full border border-[#e9b21a] text-[#e9b21a] hover:bg-[#e9b21a] hover:text-black transition"
                >
                  View Details
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* VIEW MORE */}
        {!showAll && programs.length > 6 && (
          <div className="text-center mt-16">
            <button
              onClick={() => setShowAll(true)}
              className="px-8 py-3 rounded-full bg-[#e9b21a] text-black font-semibold hover:bg-[#d4a318] transition"
            >
              View More Programs
            </button>
          </div>
        )}
      </div>

      {/* ================= DETAILS PANEL ================= */}
      <AnimatePresence>
        {active && (
          <motion.div
            className="fixed inset-0 z-50 bg-black/90 backdrop-blur-xl flex items-center justify-center px-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              initial={{ x: 80, opacity: 0 }}
              animate={{ x: 0, opacity: 1 }}
              exit={{ x: 80, opacity: 0 }}
              transition={{ duration: 0.4 }}
              className="max-w-4xl w-full bg-black border border-white/10 rounded-2xl p-10"
            >
              {/* CLOSE */}
              <button
                onClick={() => setActive(null)}
                className="absolute top-6 right-6 text-gray-400 hover:text-white"
              >
                ✕
              </button>

              <h3 className="text-3xl font-bold mb-8">
                {active.title}
              </h3>

              {/* BRANCH TABS */}
              <div className="flex gap-4 mb-8 flex-wrap">
                {Object.keys(active.branches).map((b) => (
                  <button
                    key={b}
                    onClick={() => setBranch(b)}
                    className={`px-5 py-2 rounded-full border transition ${
                      branch === b
                        ? "bg-[#e9b21a] text-black border-[#e9b21a]"
                        : "border-white/20 text-gray-300"
                    }`}
                  >
                    {b}
                  </button>
                ))}
              </div>

              {/* BRANCH CONTENT */}
              <AnimatePresence mode="wait">
                <motion.p
                  key={branch}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 20 }}
                  transition={{ duration: 0.3 }}
                  className="text-gray-400 leading-relaxed"
                >
                  {active.branches[branch]}
                </motion.p>
              </AnimatePresence>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
